1	//! DevFlow stage machine.
2	//!
3	//! The workflow is a single linear chain of five stages:
4	//! Define → Plan → Code → Validate → Ship.
5	//!
6	//! - **Define / Plan / Code** launch a coding agent driven by a GSD slash command.
7	//! - **Validate / Ship** are gate stages: they may fire a gate to Hermes (the
8	//!   human interface) depending on the active [`Mode`](crate::mode::Mode).
9	
10	use serde::{Deserialize, Serialize};
11	use std::fmt;
12	
13	/// A stage in the DevFlow execution pipeline.
14	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
15	#[serde(rename_all = "lowercase")]
16	pub enum Stage {
17	    /// Gather requirements via adaptive Q&A (`/gsd-discuss-phase`).
18	    Define,
19	    /// Research + plan + verify loop (`/gsd-plan-phase`).
20	    Plan,
21	    /// Wave-based parallel execution (`/gsd-execute-phase`).
22	    Code,
23	    /// Nyquist coverage audit (`/gsd-validate-phase`).
24	    Validate,
25	    /// PR + review + merge prep (`/gsd-ship`).
26	    Ship,
27	}
28	
29	impl Stage {
30	    /// The next stage in the linear chain, or `None` after `Ship`.
31	    pub fn next(self) -> Option<Stage> {
32	        match self {
33	            Stage::Define => Some(Stage::Plan),
34	            Stage::Plan => Some(Stage::Code),
35	            Stage::Code => Some(Stage::Validate),
36	            Stage::Validate => Some(Stage::Ship),
37	            Stage::Ship => None,
38	        }
39	    }
40	
41	    /// Whether this stage fires a gate to Hermes (Validate and Ship).
42	    pub fn is_gate(self) -> bool {
43	        matches!(self, Stage::Validate | Stage::Ship)
44	    }
45	
46	    /// Whether this stage launches a coding agent (Define, Plan, Code).
47	    pub fn is_agent_stage(self) -> bool {
48	        matches!(self, Stage::Define | Stage::Plan | Stage::Code)
49	    }
50	
51	    /// The GSD slash command for this stage, with `{N}` as the phase placeholder.
52	    ///
53	    /// D-14 note: as of the fix for the headless Define hang, DevFlow's own
54	    /// launch path no longer builds a `Stage::Define` prompt from this
55	    /// mapping — `prompt::define_stage_prompt` is what the Define stage
56	    /// actually runs, and never names or invokes this entry's command. This
57	    /// mapping's `Stage::Define` arm remains the canonical value for
58	    /// human-facing preview/documentation output (e.g. a dry-run pipeline
59	    /// listing) only.
60	    pub fn gsd_command(self) -> &'static str {
61	        match self {
62	            Stage::Define => "/gsd-discuss-phase {N}",
63	            Stage::Plan => "/gsd-plan-phase {N}",
64	            Stage::Code => "/gsd-execute-phase {N}",
65	            Stage::Validate => "/gsd-validate-phase {N}",
66	            Stage::Ship => "/gsd-ship {N}",
67	        }
68	    }
69	}
70	
71	impl fmt::Display for Stage {
72	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
73	        let name = match self {
74	            Stage::Define => "define",
75	            Stage::Plan => "plan",
76	            Stage::Code => "code",
77	            Stage::Validate => "validate",
78	            Stage::Ship => "ship",
79	        };
80	        f.write_str(name)
81	    }
82	}
83	
84	impl std::str::FromStr for Stage {
85	    type Err = StageParseError;
86	
87	    fn from_str(value: &str) -> Result<Self, Self::Err> {
88	        match value.to_ascii_lowercase().as_str() {
89	            "define" => Ok(Stage::Define),
90	            "plan" => Ok(Stage::Plan),
91	            "code" => Ok(Stage::Code),
92	            "validate" => Ok(Stage::Validate),
93	            "ship" => Ok(Stage::Ship),
94	            other => Err(StageParseError(other.to_string())),
95	        }
96	    }
97	}
98	
99	/// Error returned when parsing an unsupported stage name.
100	#[derive(Debug, Clone, thiserror::Error)]
101	#[error("unsupported stage `{0}`; expected define, plan, code, validate, or ship")]
102	pub struct StageParseError(String);
103	
