101	fn extract_tokens(text: &str, prefix: &str, allowed: impl Fn(char) -> bool) -> Vec<String> {
102	    let mut found = Vec::new();
103	    let mut offset = 0;
104	    while let Some(index) = text[offset..].find(prefix) {
105	        let start = offset + index;
106	        let end = text[start..]
107	            .char_indices()
108	            .take_while(|(index, ch)| *index < prefix.len() || allowed(*ch))
109	            .last()
110	            .map(|(index, ch)| start + index + ch.len_utf8())
111	            .unwrap_or(start + prefix.len());
112	        found.push(text[start..end].to_owned());
113	        offset = end.max(start + prefix.len());
114	    }
115	    found.sort();
116	    found.dedup();
117	    found
118	}
