120	fn documented_subcommands(docs: &str) -> Vec<String> {
121	    extract_tokens(docs, "devflow ", |ch| ch.is_ascii_lowercase() || ch == '-')
122	        .into_iter()
123	        .filter_map(|token| token.split_whitespace().nth(1).map(str::to_owned))
124	        .collect()
125	}
126	
127	fn documented_flags(docs: &str) -> Vec<String> {
128	    let mut flags: Vec<_> = docs
129	        .split_whitespace()
130	        .map(|word| {
131	            word.trim_matches(|ch: char| {
132	                matches!(
133	                    ch,
134	                    '`' | '[' | ']' | '(' | ')' | ',' | '.' | ':' | '|' | '"'
135	                )
136	            })
137	        })
138	        .filter(|word| {
139	            word.starts_with("--")
140	                && word.len() > 2
141	                && word[2..]
142	                    .chars()
143	                    .all(|ch| ch.is_ascii_lowercase() || ch == '-')
144	        })
145	        .map(str::to_owned)
146	        .collect();
147	    flags.sort();
148	    flags.dedup();
149	    flags
150	}
151	
152	fn documented_rust_identifiers(docs: &str) -> Vec<String> {
153	    let mut identifiers = Vec::new();
154	    for (index, span) in docs.split('`').enumerate() {
155	        if index % 2 == 0 || span.chars().any(char::is_whitespace) {
156	            continue;
157	        }
158	        let callable = span.contains('(');
159	        let qualified = span.contains("::");
160	        let base = span
161	            .split('(')
162	            .next()
163	            .unwrap_or(span)
164	            .trim_end_matches("()");
165	        let identifier = base.rsplit("::").next().unwrap_or(base);
166	        let upper_camel = identifier.chars().next().is_some_and(char::is_uppercase)
167	            && identifier.chars().any(char::is_lowercase);
168	        if (callable || qualified || upper_camel)
169	            && !identifier.is_empty()
170	            && identifier
171	                .chars()
172	                .all(|ch| ch.is_ascii_alphanumeric() || ch == '_')
173	        {
174	            identifiers.push(identifier.to_owned());
175	        }
176	    }
177	    identifiers.sort();
178	    identifiers.dedup();
179	    identifiers
180	}
181	
182	fn enum_variants(source: &str, enum_name: &str) -> Vec<String> {
183	    let marker = format!("enum {enum_name} {{");
184	    let body = source
185	        .split_once(&marker)
186	        .map(|(_, body)| body)
187	        .unwrap_or("");
188	    let mut depth = 1_i32;
189	    let mut variants = Vec::new();
190	    for line in body.lines() {
191	        if depth == 1 {
192	            let trimmed = line.trim();
193	            if let Some(name) = trimmed
194	                .split(['{', ','])
195	                .next()
196	                .map(str::trim)
197	                .filter(|name| {
198	                    !name.is_empty()
199	                        && name.chars().next().is_some_and(char::is_uppercase)
200	                        && name.chars().all(char::is_alphabetic)
201	                })
202	            {
203	                variants.push(name.to_ascii_lowercase());
204	            }
205	        }
206	        depth += line.matches('{').count() as i32;
207	        depth -= line.matches('}').count() as i32;
208	        if depth <= 0 {
209	            break;
210	        }
211	    }
212	    variants.sort();
213	    variants.dedup();
214	    variants
215	}
